import unittest

from warehouse import low_stock, total_value, apply_discount

ITEMS = {
    "bolt": {"quantity": 12, "price": 2},
    "nut": {"quantity": 4, "price": 1},
    "brace": {"quantity": 6, "price": 5},
}

class LowStockTest(unittest.TestCase):
    def test_below_threshold_is_exclusive(self):
        self.assertEqual(low_stock(ITEMS, 6), ["nut"])

    def test_threshold_value_itself_excluded(self):
        self.assertEqual(low_stock(ITEMS, 4), [])

class TotalValueTest(unittest.TestCase):
    def test_sum(self):
        self.assertEqual(total_value(ITEMS), 12*2 + 4*1 + 6*5)

class ApplyDiscountTest(unittest.TestCase):
    def test_returns_new_mapping_without_mutating_input(self):
        import copy
        original = copy.deepcopy(ITEMS)
        discounted = apply_discount(ITEMS, 50)
        self.assertEqual(discounted["bolt"]["price"], 1)
        self.assertEqual(ITEMS["bolt"]["price"], 2)
        self.assertEqual(original, ITEMS)

